"""
Library for Trustable score calculations.

In practice, this means functions for interfacing between [dotstop][trudag.dotstop] and [graphalyzer][trudag.graphalyzer].
"""

import logging
from pathlib import Path

import numpy as np

import trudag.graphalyzer.analysis as gzranalysis
import trudag.graphalyzer.graph as gzrgraph
import trudag.utils as utils
from trudag.dotstop import Item
from trudag.dotstop.core.graph import LinkStatus, TrustableGraph
from trudag.dotstop.core.validator import Validator

logger = logging.getLogger(__name__)


def score(
    graph: TrustableGraph, validator: Validator | None = None, dump: Path | None = None
) -> dict[str, tuple[float, str]]:
    """
    Compute the trustable score of `graph` and all its reviewed `Item`s.

    The score is calculated recursively from leaf `Item`s, with each
    `Item` being assigned a score equal to the weighted sum of its child
    `Item`s. The score for each leaf `Item` should be recorded in an
    attribute named [`score`][trudag.dotstop.core.item.Item.score],
    else its score will be assumed to be zero.

    Unreviewed `Item`s will not be scored. Contributions from child
    `Item`s associated by a suspect link are ignored.

    Warning:
        Scoring is still under heavy development. Currently:

        - Scores for non-leaf nodes are ignored.
        - All weights are assumed to be one and are normalized accordingly.

        This behaviour is likely to change.

    Args:
        graph (TrustableGraph): Graph to score.
        validator (Validator | None): Validator class object to run validations with.
        dump (Path): Output file path for the Trustable Scores file

    Returns:
        (dict[str, float]): Dictionary of (UID, confidence score) pairs for all reviewed `Item`s.
    """
    # Filter non-normative items, don't need to check edges
    # because normative -> non-normative edge is not possible.
    valid_graph = graph.subgraph(
        lambda node: graph.get_item(node).normative,
        lambda _src, _dst: True,
    )
    adjacency = valid_graph.adjacency
    num_items = len(adjacency)
    item_names = [item.name for item in valid_graph.items]
    shadowed = np.pad(
        adjacency, ((0, num_items), (0, num_items)), mode="constant", constant_values=0
    )
    # When a link is suspect or an item is unreviewed, the source node instead points to a "NULL"
    # version of the destination node that has a score 0.
    for i in range(num_items):
        for j in range(i, num_items):
            if not shadowed[i][j]:
                continue
            src, dst = item_names[i], item_names[j]
            if (
                not valid_graph.get_review_status(src)
                or not valid_graph.get_review_status(dst)
                or valid_graph.get_link_status(src, dst) == LinkStatus.SUSPECT
            ):
                shadowed[i][j] = 0.0
                shadowed[i][num_items + j] = 1.0

    validations = {}
    review_statuses = {}
    for item in graph.items:
        if validator:
            validations[item.name] = item.validation(validator)
        review_statuses[item.name] = graph.get_review_status(item.name)
    premises = graph.get_premises()

    evidence_score_dict = scores_from_graph(
        premises=premises, review_statuses=review_statuses, validations=validations
    )
    item_names.extend((f"NULL_{item.name}" for item in valid_graph.items))
    evidence_score_dict.update({f"NULL_{name}": 0 for name in item_names})
    digraph = gzrgraph.DirectedAcyclicGraph(shadowed, item_names).normalized()
    scores = gzranalysis.score(digraph, evidence_score_dict)
    scores = {
        item_name: (
            round(score, 5),
            score_origin(
                graph.get_item(item_name), premises, review_statuses, validations, score
            ),
        )
        for item_name, score in scores.items()
        if not item_name.startswith("NULL")
    }

    # dump scores to an output file if any output path is provided
    utils.dump_scores(scores, dump)
    return scores


def item_sensitivity(graph: TrustableGraph, items_labels: list[str] | None = None):
    """
    Do the sensitivity analysis for a given TrustableGraph or to a certain
    set of nodes using items_labels filter

    Args:
         graph (TrustableGraph): Graph to be analysed
         items_labels (list[str]): Optional items filter to be evaluated
    Returns:
        (dict[str, dict[str,float]]): Dictionary of items and with a map of how that item is important to the others items
    """
    items: list[str] = (
        items_labels if items_labels else [item.name for item in graph.items]
    )
    digraph = gzrgraph.DirectedAcyclicGraph(graph.adjacency, items).normalized()
    return {item: gzranalysis.score_node_sensitivity(digraph, item) for item in items}


def scores_from_graph(
    premises: list[Item],
    review_statuses: dict[str, bool],
    validations: dict[str, dict],
) -> dict[str, float]:
    """
    Given premises with their review statuses and validations, extract the Evidence scores.

    Where items have neither an SME or validation score, assign them a score of
    zero, logging a warning.
    Where items have an SME score but are missing a validation score AND references, assign them a score
    of zero, logging a warning.
    Where items have both an SME and validation score,
    take their product.

    Args:
        premises (dotstop.Graph): List of premises to extract Evidence scores from.
        review_statuses (dict[str, bool]): review statuses of all items.
        validations (dict[str, dict]): validation results of all items.

    Returns:
        (dict[str, float]): Dictionary of (item_str, confidence score) pairs for Evidence items
    """
    evidence_score_dict = {}
    for evidence in premises:
        if not review_statuses[evidence.name]:
            evidence_score_dict[evidence.name] = 0.0
            continue
        sme_score = evidence.score
        validator = validations.get(evidence.name)
        validator_score = validator.get("score") if validator else None
        if sme_score is None and validator_score is None:
            logger.warning(
                f"Score not provided for Item {evidence.name}. Score set to zero."
            )
            evidence_score_dict[evidence.name] = 0.0
        else:
            if (sme_score is not None) and (
                (validator_score is None) and not evidence.references()
            ):
                logger.warning(
                    f"Score provided for Item {evidence.name} is invalid, no validator or artifact provided for the score. Score set to zero."
                )
                evidence_score_dict[evidence.name] = 0.0
                continue
            sme_score = 1.0 if sme_score is None else sme_score
            validator_score = 1.0 if validator_score is None else validator_score
            evidence_score_dict[evidence.name] = sme_score * validator_score
    return evidence_score_dict


def score_origin(
    item: Item,
    premises: list[Item],
    review_statuses: dict[str, bool],
    validations: dict[str, dict],
    score: float,
) -> str:
    """
    Given an item extracts its score origin.
    """
    if item not in premises and review_statuses[item.name] and score > 0.0:
        return "Derived from supporting Statements"

    rules = (
        (
            lambda item: bool(item.sme_scores)
            and bool(item.references())
            and bool(validations.get(item.name)),
            "SME with References and Validator",
        ),
        (
            lambda item: bool(item.sme_scores) and bool(item.references()),
            "SME with References",
        ),
        (
            lambda item: bool(item.sme_scores) and bool(validations.get(item.name)),
            "SME with Validator",
        ),
        (
            lambda item: bool(validations.get(item.name)) and bool(item.references()),
            "Validator with References",
        ),
        (
            lambda item: bool(validations.get(item.name)),
            "Validator",
        ),
    )

    for matches_rule, value in rules:
        if matches_rule(item) and review_statuses[item.name]:
            return value
    return "Missing"
